### Solution E: Memory-Based Data Storage

**Description:**
- This implementation uses memory to store blockchain data without relying on external databases.
- It utilizes a simple HTTP server to handle requests.

**Code:**

```java
import com.google.gson.Gson;
import com.sun.net.httpserver.HttpServer;
import com.sun.net.httpserver.HttpHandler;
import com.sun.net.httpserver.HttpExchange;

import java.io.OutputStream;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

class Block {
    private int index;
    private String previousHash;
    private long timestamp;
    private String data;
    private String hash;

    public Block(int index, String previousHash, long timestamp, String data) {
        this.index = index;
        this.previousHash = previousHash;
        this.timestamp = timestamp;
        this.data = data;
        this.hash = calculateHash();
    }

    public String calculateHash() {
        String text = index + previousHash + timestamp + data;
        MessageDigest digest;
        byte[] hashBytes;
        try {
            digest = MessageDigest.getInstance("SHA-256");
            hashBytes = digest.digest(text.getBytes());
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    // Getters
    public int getIndex() { return index; }
    public String getPreviousHash() { return previousHash; }
    public long getTimestamp() { return timestamp; }
    public String getData() { return data; }
    public String getHash() { return hash; }

    // JSON Representation
    public String toJson() {
        return new Gson().toJson(this);
    }
}

class Blockchain {
    private List<Block> chain;

    public Blockchain() {
        chain = new ArrayList<>();
        chain.add(generateGenesisBlock());
    }

    private Block generateGenesisBlock() {
        return new Block(0, "0", System.currentTimeMillis(), "Genesis Block");
    }

    public Block getLatestBlock() {
        return chain.get(chain.size() - 1);
    }

    public void addBlock(String data) {
        Block previousBlock = getLatestBlock();
        int index = previousBlock.getIndex() + 1;
        String previousHash = previousBlock.getHash();
        long timestamp = System.currentTimeMillis();
        Block newBlock = new Block(index, previousHash, timestamp, data);
        chain.add(newBlock);
    }

    public List<Block> getChain() {
        return chain;
    }

    public String toJson() {
        return new Gson().toJson(chain);
    }
}

public class BlockchainServerE {
    public static void main(String[] args) throws IOException {
        Blockchain blockchain = new Blockchain();
        HttpServer server = HttpServer.create(new InetSocketAddress(8000), 0);

        server.createContext("/chain", new HttpHandler() {
            @Override
            public void handle(HttpExchange exchange) throws IOException {
                String response = blockchain.toJson();
                exchange.sendResponseHeaders(200, response.length());
                OutputStream os = exchange.getResponseBody();
                os.write(response.getBytes());
                os.close();
            }
        });

        server.createContext("/mine", new HttpHandler() {
            @Override
            public void handle(HttpExchange exchange) throws IOException {
                if ("POST".equals(exchange.getRequestMethod())) {
                    blockchain.addBlock("New Block by server");
                    String response = "Block mined successfully";
                    exchange.sendResponseHeaders(200, response.length());
                    OutputStream os = exchange.getResponseBody();
                    os.write(response.getBytes());
                    os.close();
                } else {
                    exchange.sendResponseHeaders(405, -1); // Method Not Allowed
                }
            }
        });

        server.setExecutor(null); // creates a default executor
        server.start();

        System.out.println("Blockchain server is running on port 8000");
    }
}
```

### Solution F: File System-Based Data Storage

**Description:**
- This implementation stores blockchain data in a local file.
- It also uses a simple HTTP server to handle requests.

**Code:**

```java
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.sun.net.httpserver.HttpServer;
import com.sun.net.httpserver.HttpHandler;
import com.sun.net.httpserver.HttpExchange;

import java.io.*;
import java.net.InetSocketAddress;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

class BlockF {
    private int index;
    private String previousHash;
    private long timestamp;
    private String data;
    private String hash;

    public BlockF(int index, String previousHash, long timestamp, String data) {
        this.index = index;
        this.previousHash = previousHash;
        this.timestamp = timestamp;
        this.data = data;
        this.hash = calculateHash();
    }

    public String calculateHash() {
        String text = index + previousHash + timestamp + data;
        MessageDigest digest;
        byte[] hashBytes;
        try {
            digest = MessageDigest.getInstance("SHA-256");
            hashBytes = digest.digest(text.getBytes());
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    // Getters
    public int getIndex() { return index; }
    public String getPreviousHash() { return previousHash; }
    public long getTimestamp() { return timestamp; }
    public String getData() { return data; }
    public String getHash() { return hash; }

    // JSON Representation
    public String toJson() {
        return new Gson().toJson(this);
    }
}

class BlockchainF {
    private static final String FILE_NAME = "blockchain.json";
    private List<BlockF> chain;

    public BlockchainF() {
        chain = loadChain();
        if (chain.isEmpty()) {
            chain.add(generateGenesisBlock());
            saveChain();
        }
    }

    private BlockF generateGenesisBlock() {
        return new BlockF(0, "0", System.currentTimeMillis(), "Genesis Block");
    }

    private List<BlockF> loadChain() {
        try (Reader reader = new FileReader(FILE_NAME)) {
            return new Gson().fromJson(reader, new TypeToken<List<BlockF>>(){}.getType());
        } catch (IOException e) {
            return new ArrayList<>();
        }
    }

    private void saveChain() {
        try (Writer writer = new FileWriter(FILE_NAME)) {
            new Gson().toJson(chain, writer);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public BlockF getLatestBlock() {
        return chain.get(chain.size() - 1);
    }

    public void addBlock(String data) {
        BlockF previousBlock = getLatestBlock();
        int index = previousBlock.getIndex() + 1;
        String previousHash = previousBlock.getHash();
        long timestamp = System.currentTimeMillis();
        BlockF newBlock = new BlockF(index, previousHash, timestamp, data);
        chain.add(newBlock);
        saveChain();
    }

    public List<BlockF> getChain() {
        return chain;
    }

    public String toJson() {
        return new Gson().toJson(chain);
    }
}

public class BlockchainServerF {
    public static void main(String[] args) throws IOException {
        BlockchainF blockchain = new BlockchainF();
        HttpServer server = HttpServer.create(new InetSocketAddress(8001), 0);

        server.createContext("/chain", new HttpHandler() {
            @Override
            public void handle(HttpExchange exchange) throws IOException {
                String response = blockchain.toJson();
                exchange.sendResponseHeaders(200, response.length());
                OutputStream os = exchange.getResponseBody();
                os.write(response.getBytes());
                os.close();
            }
        });

        server.createContext("/mine", new HttpHandler() {
            @Override
            public void handle(HttpExchange exchange) throws IOException {
                if ("POST".equals(exchange.getRequestMethod())) {
                    blockchain.addBlock("New Block by server");
                    String response = "Block mined successfully";
                    exchange.sendResponseHeaders(200, response.length());
                    OutputStream os = exchange.getResponseBody();
                    os.write(response.getBytes());
                    os.close();
                } else {
                    exchange.sendResponseHeaders(405, -1); // Method Not Allowed
                }
            }
        });

        server.setExecutor(null); // creates a default executor
        server.start();

        System.out.println("Blockchain server is running on port 8001");
    }
}
```

The key difference between these two solutions is that Solution E stores blockchain data in memory, while Solution F persists the data in the file system, ensuring data is not lost after a restart. Each approach has its own advantages and disadvantages, and the choice depends on your specific requirements and use case.

