# Distributed Lock Implementation in MySQL

## Pseudo Code
```
function acquireLock(lockName, timeout):
    // Attempt to insert lock record
    result = executeSQL("INSERT INTO distributed_locks (lock_name, owner_id, created_at, expires_at) VALUES (?, ?, NOW(), DATE_ADD(NOW(), INTERVAL ? SECOND))", 
                       [lockName, generateUUID(), timeout])

    if result.affectedRows == 1:
        return true  // Lock acquired successfully
    else:
        // Check if existing lock has expired
        existingLock = executeSQL("SELECT lock_name FROM distributed_locks WHERE lock_name = ? AND expires_at > NOW() FOR UPDATE", [lockName])

        if existingLock.isEmpty():
            // Try to update expired lock
            updateResult = executeSQL("UPDATE distributed_locks SET owner_id = ?, created_at = NOW(), expires_at = DATE_ADD(NOW(), INTERVAL ? SECOND) WHERE lock_name = ? AND expires_at <= NOW()", 
                                    [generateUUID(), timeout, lockName])
            return updateResult.affectedRows == 1
        else:
            return false  // Lock is held by someone else

function releaseLock(lockName, ownerId):
    executeSQL("DELETE FROM distributed_locks WHERE lock_name = ? AND owner_id = ?", [lockName, ownerId])

function modifyWithLock(resourceId, newValue):
    lockName = "resource_" + resourceId
    ownerId = generateUUID()

    try:
        if acquireLock(lockName, 30):  // 30 second timeout
            // Critical section
            result = executeSQL("UPDATE resources SET value = ? WHERE id = ?", [newValue, resourceId])
            releaseLock(lockName, ownerId)
            return result.affectedRows > 0 ? "SUCCESS" : "FAILURE"
        else:
            return "FAILURE (LOCK_NOT_ACQUIRED)"
    except Exception as e:
        releaseLock(lockName, ownerId)
        return "FAILURE (EXCEPTION)"
